/* ================================================================ */
/* SNOW tileset                                                     */
/* ================================================================ */
enum {
  MT_SN_SNOW,  /* fresh snow (+ SNOW2 footprints, SNOW3 kin tracks and a twig) */
  MT_SN_SNOW2,
  MT_SN_SNOW3,
  MT_SN_DRIFT,  /* snow drift with frosted grass: wild kin roam here; top layer hides legs */
  MT_SN_PINE_TOP,  /* 16x32 snowy pine: TOP above BOTTOM (overlay, ground drawn beneath) */
  MT_SN_PINE_BOTTOM,
  MT_SN_LEDGE,  /* icy ledge: walk DOWN onto it to hop over; tiles horizontally */
  MT_SN_LEDGE_L,
  MT_SN_LEDGE_R,
  MT_SN_CLIFF,  /* granite wall with a snow cap on top (solid); stack CLIFF_FACE below */
  MT_SN_CLIFF_FACE,
  MT_SN_CRAG,  /* wind-carved snowbank with rock showing (solid) */
  MT_SN_STONE,  /* slate cobbles with snow in the joints (Frosthollow plaza) */
  MT_SN_ICE,  /* frozen pond (A_ICE: you slide until blocked); ICE_* have a snowy rim */
  MT_SN_ICE_N,
  MT_SN_ICE_S,
  MT_SN_ICE_W,
  MT_SN_ICE_E,
  MT_SN_ICE_NW,
  MT_SN_ICE_NE,
  MT_SN_ICE_SW,
  MT_SN_ICE_SE,
  MT_SN_ICE_ROCK,  /* granite boulder frozen into the ice (solid) */
  MT_SN_CLOUD,  /* the sea of clouds around the Sky Isle (solid) */
  MT_SN_HALL_FLOOR,  /* Rime Hall flagstones */
  MT_SN_HALL_WALL_TOP,  /* upper hall wall of frosted ice bricks */
  MT_SN_HALL_WALL,  /* lower hall wall with a granite skirting */
  MT_SN_HALL_MAT,  /* exit mat (A_EXIT) on the flagstones */
  MT_SN_VOID,  /* outside a room */
  MT_SN_DRIFT_B,
  MT_SN_DRIFT_C,
  MT_SN_TERRAIN_COUNT
};
